import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { createRound, stepRound, botView, roundPlan } from '../../../../arena/engine.js';

const root = resolve('.');
const botPath = pathToFileURL(resolve(root, 'lab/opponents/fable/bot.js')).href;
let inst = 0;

async function loadMine(code) {
  const mod = await import(`${botPath}?i=${inst++}`);
  const bot = mod.default;
  const [armor, engine, gun, reload] = code.split('').map(Number);
  bot.stats = { armor, engine, gun, reload };
  return { bot, name: `F${code}`, stats: bot.stats };
}
async function loadSparring(name) {
  const mod = await import(pathToFileURL(resolve(root, `arena/sparring/${name}/bot.js`)).href + `?i=${inst++}`);
  return { bot: mod.default, name, stats: mod.default.stats };
}

function play(a, b, rounds) {
  const res = { aw: 0, bw: 0, draw: 0, aHp: 0, bHp: 0, time: 0, aTick: 0, calls: 0 };
  for (let i = 0; i < rounds; i++) {
    const plan = roundPlan(i);
    const bySide = plan.swap ? [b, a] : [a, b];
    const round = createRound({ mapIndex: plan.mapIndex, tanks: bySide.map((e) => ({ name: e.name, stats: e.stats })) });
    for (let s = 0; s < 2; s++) bySide[s].bot.init?.({ round: i, side: s, mapName: round.map.name, view: botView(round, s) });
    while (!round.over) {
      const actions = [0, 1].map((s) => {
        const t0 = performance.now();
        const out = bySide[s].bot.tick(botView(round, s));
        if (bySide[s] === a) { res.aTick += performance.now() - t0; res.calls++; }
        return out;
      });
      stepRound(round, actions);
    }
    const aSide = plan.swap ? 1 : 0;
    if (round.winner === null) res.draw++;
    else if (round.winner === aSide) res.aw++;
    else res.bw++;
