// Временный стенд: гоняет варианты характеристик моего бота друг против друга
// и против спарринг-ботов. Запуск из C:\tank-arena\contestants\opus:
//   node lab/opponents/fable/dev/tourney.mjs rr 1432,2332,0433 [rounds]
//   node lab/opponents/fable/dev/tourney.mjs vs hunter 1432,2332 [rounds]
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { createRound, stepRound, botView, roundPlan } from '../../../../arena/engine.js';

const root = resolve('.');
const botPath = pathToFileURL(resolve(root, 'lab/opponents/fable/bot.js')).href;
let inst = 0;

async function loadMine(code) {
  const mod = await import(`${botPath}?i=${inst++}`);
  const bot = mod.default;
  const [armor, engine, gun, reload] = code.split('').map(Number);
  bot.stats = { armor, engine, gun, reload };
  return { bot, name: `F${code}`, stats: bot.stats };
}
async function loadSparring(name) {
  const mod = await import(pathToFileURL(resolve(root, `arena/sparring/${name}/bot.js`)).href + `?i=${inst++}`);
  return { bot: mod.default, name, stats: mod.default.stats };
}

function play(a, b, rounds) {
  const res = { aw: 0, bw: 0, draw: 0, aHp: 0, bHp: 0, time: 0, aTick: 0, calls: 0 };
  for (let i = 0; i < rounds; i++) {
    const plan = roundPlan(i);
    const bySide = plan.swap ? [b, a] : [a, b];
    const round = createRound({ mapIndex: plan.mapIndex, tanks: bySide.map((e) => ({ name: e.name, stats: e.stats })) });
    for (let s = 0; s < 2; s++) bySide[s].bot.init?.({ round: i, side: s, mapName: round.map.name, view: botView(round, s) });
    while (!round.over) {
      const actions = [0, 1].map((s) => {
        const t0 = performance.now();
        const out = bySide[s].bot.tick(botView(round, s));
        if (bySide[s] === a) { res.aTick += performance.now() - t0; res.calls++; }
        return out;
      });
      stepRound(round, actions);
    }
    const aSide = plan.swap ? 1 : 0;
    if (round.winner === null) res.draw++;
    else if (round.winner === aSide) res.aw++;
    else res.bw++;
    res.aHp += round.tanks[aSide].hp / round.tanks[aSide].stats.maxHp;
    res.bHp += round.tanks[1 - aSide].hp / round.tanks[1 - aSide].stats.maxHp;
    res.time += round.time;
  }
  return res;
}

const [mode, arg1, arg2, arg3] = process.argv.slice(2);
if (mode === 'rr') {
  const codes = arg1.split(',');
  const rounds = Number(arg2 || 8);
  const bots = [];
  for (const c of codes) bots.push(await loadMine(c));
  const score = Object.fromEntries(codes.map((c) => [c, { pts: 0, w: 0, l: 0, d: 0 }]));
  for (let i = 0; i < bots.length; i++) {
    for (let j = i + 1; j < bots.length; j++) {
      const r = play(bots[i], bots[j], rounds);
      score[codes[i]].w += r.aw; score[codes[i]].l += r.bw; score[codes[i]].d += r.draw;
      score[codes[j]].w += r.bw; score[codes[j]].l += r.aw; score[codes[j]].d += r.draw;
      console.log(`${codes[i]} vs ${codes[j]}: ${r.aw}-${r.bw}-${r.draw}  hp ${(r.aHp / rounds).toFixed(2)} vs ${(r.bHp / rounds).toFixed(2)}  avg ${(r.time / rounds).toFixed(0)}s`);
    }
  }
  console.log('\nИтог:');
  for (const c of codes.sort((x, y) => (score[y].w - score[y].l) - (score[x].w - score[x].l))) {
    console.log(`${c}: +${score[c].w} -${score[c].l} =${score[c].d}`);
  }
} else if (mode === 'vs') {
  const foe = await loadSparring(arg1);
  const rounds = Number(arg3 || 8);
  for (const c of arg2.split(',')) {
    const me = await loadMine(c);
    const r = play(me, foe, rounds);
    console.log(`${c} vs ${arg1}: ${r.aw}-${r.bw}-${r.draw}  hp ${(r.aHp / rounds).toFixed(2)} vs ${(r.bHp / rounds).toFixed(2)}  avg ${(r.time / rounds).toFixed(0)}s  tick ${(r.aTick / r.calls).toFixed(3)}ms`);
  }
}

