// Трассировка одного раунда: события выстрелов/попаданий с дистанцией.
//   node lab/opponents/fable/dev/trace.mjs [mapIndex] [specA] [specB]
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { createRound, stepRound, botView } from '../../../../arena/engine.js';

const root = resolve('.');
const botPath = pathToFileURL(resolve(root, 'lab/opponents/fable/bot.js')).href;
const PERSONAS = { close: { rMin: 210, rMax: 340, adapt: false }, noadapt: { adapt: false } };
let inst = 0;
async function loadMine(spec) {
  const [code, persona] = spec.split(':');
  const mod = await import(`${botPath}?i=${inst++}`);
  const bot = mod.default;
  const [armor, engine, gun, reload] = code.split('').map(Number);
  bot.stats = { armor, engine, gun, reload };
  if (persona) Object.assign(bot.tune, PERSONAS[persona]);
  return { bot, name: spec, stats: bot.stats };
}
const mapIndex = Number(process.argv[2] || 0);
const a = await loadMine(process.argv[3] || '1432');
const b = await loadMine(process.argv[4] || '1432');
const bySide = [a, b];
const round = createRound({ mapIndex, tanks: bySide.map((e) => ({ name: e.name, stats: e.stats })) });
for (let s = 0; s < 2; s++) bySide[s].bot.init?.({ round: 0, side: s, mapName: round.map.name, view: botView(round, s) });
let lastLog = -1;
while (!round.over) {
  const actions = [0, 1].map((s) => bySide[s].bot.tick(botView(round, s)));
  const events = stepRound(round, actions);
  const [t0, t1] = round.tanks;
  const d = Math.hypot(t0.x - t1.x, t0.y - t1.y);
  for (const e of events) {
    if (e.type === 'shot') console.log(`${round.time.toFixed(2)}s shot by ${e.side} dist=${d.toFixed(0)} speeds=${t0.speed.toFixed(0)}/${t1.speed.toFixed(0)}`);
    if (e.type === 'hit' && e.cause !== 'zone') console.log(`${round.time.toFixed(2)}s HIT on ${e.side} -${e.damage} dist=${d.toFixed(0)} hp=${t0.hp.toFixed(0)}/${t1.hp.toFixed(0)}${e.ricochet ? ' rico' : ''}`);
    if (e.type === 'pickup') console.log(`${round.time.toFixed(2)}s kit by ${e.side} +${e.healed}`);
  }
  if (Math.floor(round.time) !== lastLog) {
    lastLog = Math.floor(round.time);
    console.log(`  t=${lastLog}s dist=${d.toFixed(0)} A(${t0.x.toFixed(0)},${t0.y.toFixed(0)}) B(${t1.x.toFixed(0)},${t1.y.toFixed(0)}) hp=${t0.hp.toFixed(0)}/${t1.hp.toFixed(0)}`);
  }
}
console.log('winner', round.winner, round.endReason, round.time.toFixed(1));

