cat > lab/opponents/fable/dev/zonecheck.mjs <<'EOF'
// Пацифисты на всех картах с обеих сторон: сколько HP теряется в зоне.
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { createRound, stepRound, botView } from '../../../../arena/engine.js';
const botPath = pathToFileURL(resolve('.', 'lab/opponents/fable/bot.js')).href;
let inst = 0;
async function load(code) {
  const bot = (await import(`${botPath}?z=${inst++}`)).default;
  const [armor, engine, gun, reload] = code.split('').map(Number);
  bot.stats = { armor, engine, gun, reload }; bot.tune.noFire = true;
  return bot;
}
for (const code of ['1342', '3331', '2350']) {
  for (let m = 0; m < 4; m++) {
    const a = await load(code), b = await load(code);
    const round = createRound({ mapIndex: m, tanks: [a, b].map((e) => ({ name: code, stats: e.stats })) });
    a.init({ round: m, side: 0, mapName: round.map.name, view: botView(round, 0) });
    b.init({ round: m, side: 1, mapName: round.map.name, view: botView(round, 1) });
    while (!round.over) stepRound(round, [a.tick(botView(round, 0)), b.tick(botView(round, 1))]);
    const [t0, t1] = round.tanks;
    console.log(code, round.map.name, `zone dmg ${t0.tally.zoneDamage.toFixed(0)} / ${t1.tally.zoneDamage.toFixed(0)}`, round.endReason, round.time.toFixed(0));
  }
}
EOF
node lab/opponents/fable/dev/zonecheck.mjs

